Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Grilla de tiles KPI con termómetro vertical IBCS y cross-filter por clic.",
  "width": 860,
  "height": 470,
  "padding": 0,
  "autosize": {
    "type": "none",
    "contains": "padding"
  },
  "config": {
    "text": {
      "font": "Segoe UI, Inter, -apple-system, Helvetica Neue, sans-serif"
    }
  },
  "signals": [
    {
      "name": "topN",
      "value": 6,
      "bind": {
        "input": "range",
        "min": 3,
        "max": 12,
        "step": 1,
        "name": "Top N  "
      }
    },
    {
      "name": "cols",
      "value": 3
    },
    {
      "name": "rows",
      "update": "ceil(topN / cols)"
    },
    {
      "name": "headerH",
      "update": "clamp(height * 0.15, 54, 76)"
    },
    {
      "name": "footerH",
      "value": 26
    },
    {
      "name": "gridPad",
      "value": 10
    },
    {
      "name": "gridX0",
      "update": "gridPad"
    },
    {
      "name": "gridX1",
      "update": "width - gridPad"
    },
    {
      "name": "gridY0",
      "update": "headerH + 8"
    },
    {
      "name": "gridY1",
      "update": "height - footerH - 4"
    },
    {
      "name": "tileW",
      "update": "bandwidth(''col'')"
    },
    {
      "name": "tileH",
      "update": "bandwidth(''row'')"
    },
    {
      "name": "topReserve",
      "value": 46
    },
    {
      "name": "bottomReserve",
      "value": 22
    },
    {
      "name": "chartH",
      "update": "max(tileH - topReserve - bottomReserve, 20)"
    },
    {
      "name": "acW",
      "update": "clamp(tileW * 0.22, 20, 40)"
    },
    {
      "name": "pyW",
      "update": "clamp(tileW * 0.12, 10, 20)"
    },
    {
      "name": "barGap",
      "value": 8
    }
  ],
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "kpi",
      "source": "dataset",
      "transform": [
        {
          "type": "filter",
          "expr": "isValid(datum[''Categoría'']) && isValid(datum.Real)"
        },
        {
          "type": "formula",
          "as": "cumpl",
          "expr": "isValid(datum.Objetivo) && datum.Objetivo != 0 ? datum.Real / datum.Objetivo : null"
        },
        {
          "type": "formula",
          "as": "varPy",
          "expr": "isValid(datum[''Año anterior'']) && datum[''Año anterior''] != 0 ? datum.Real / datum[''Año anterior''] - 1 : null"
        },
        {
          "type": "formula",
          "as": "tono",
          "expr": "datum.cumpl == null ? ''#5B6675'' : datum.cumpl >= 1 ? ''#0F766E'' : datum.cumpl >= 0.97 ? ''#B45309'' : ''#BE123C''"
        },
        {
          "type": "formula",
          "as": "op",
          "expr": "datum.__selected__ == ''off'' ? 0.32 : 1"
        },
        {
          "type": "formula",
          "as": "activa",
          "expr": "datum.__selected__ == ''on''"
        },
        {
          "type": "window",
          "ops": [
            "dense_rank"
          ],
          "as": [
            "puesto"
          ],
          "sort": {
            "field": "Real",
            "order": "descending"
          }
        },
        {
          "type": "filter",
          "expr": "datum.puesto <= topN"
        },
        {
          "type": "formula",
          "as": "col",
          "expr": "(datum.puesto - 1) % cols"
        },
        {
          "type": "formula",
          "as": "row",
          "expr": "floor((datum.puesto - 1) / cols)"
        }
      ]
    },
    {
      "name": "resumen",
      "source": "kpi",
      "transform": [
        {
          "type": "formula",
          "as": "unoSel",
          "expr": "datum.__selected__ == ''on'' ? 1 : 0"
        },
        {
          "type": "aggregate",
          "fields": [
            "Real",
            "Año anterior",
            "unoSel",
            "Categoría"
          ],
          "ops": [
            "sum",
            "sum",
            "sum",
            "count"
          ],
          "as": [
            "tReal",
            "tPy",
            "tSel",
            "tN"
          ]
        },
        {
          "type": "formula",
          "as": "tVar",
          "expr": "datum.tPy != 0 ? datum.tReal / datum.tPy - 1 : null"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "col",
      "type": "band",
      "round": true,
      "paddingInner": 0.14,
      "paddingOuter": 0.04,
      "domain": {
        "data": "kpi",
        "field": "col",
        "sort": true
      },
      "range": {
        "signal": "[gridX0, gridX1]"
      }
    },
    {
      "name": "row",
      "type": "band",
      "round": true,
      "paddingInner": 0.16,
      "paddingOuter": 0.02,
      "domain": {
        "data": "kpi",
        "field": "row",
        "sort": true
      },
      "range": {
        "signal": "[gridY0, gridY1]"
      }
    },
    {
      "name": "v",
      "type": "linear",
      "zero": true,
      "nice": true,
      "round": true,
      "domain": {
        "fields": [
          {
            "data": "kpi",
            "field": "Real"
          },
          {
            "data": "kpi",
            "field": "Objetivo"
          },
          {
            "data": "kpi",
            "field": "Año anterior"
          }
        ]
      },
      "range": {
        "signal": "[0, chartH]"
      }
    }
  ],
  "marks": [
    {
      "name": "cabeceraEtiqueta",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "value": 2
          },
          "y": {
            "value": 6
          },
          "baseline": {
            "value": "top"
          },
          "align": {
            "value": "left"
          },
          "text": {
            "signal": "''TOTAL · '' + datum.tN + '' CATEGORÍAS''"
          },
          "fontSize": {
            "value": 10
          },
          "fontWeight": {
            "value": 700
          },
          "fill": {
            "value": "#5B6675"
          }
        }
      }
    },
    {
      "name": "cabeceraValor",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "value": 2
          },
          "y": {
            "signal": "headerH - 16"
          },
          "baseline": {
            "value": "alphabetic"
          },
          "align": {
            "value": "left"
          },
          "text": {
            "signal": "pbiFormat(datum.tReal, ''#,0,,.00M'')"
          },
          "fontSize": {
            "signal": "clamp(headerH * 0.42, 20, 30)"
          },
          "fontWeight": {
            "value": 700
          },
          "fill": {
            "value": "#0F172A"
          }
        }
      }
    },
    {
      "name": "cabeceraVariacion",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "width - 2"
          },
          "y": {
            "signal": "headerH - 18"
          },
          "baseline": {
            "value": "alphabetic"
          },
          "align": {
            "value": "right"
          },
          "text": {
            "signal": "datum.tVar == null ? \"\" : (datum.tVar >= 0 ? ''▲ +'' : ''▼ −'') + pbiFormat(abs(datum.tVar), ''0.0%'') + '' vs año anterior''"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": 600
          },
          "fill": {
            "signal": "datum.tVar == null ? ''#4B5563'' : datum.tVar >= 0 ? ''#0F766E'' : ''#BE123C''"
          }
        }
      }
    },
    {
      "name": "cabeceraPista",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "width - 2"
          },
          "y": {
            "value": 6
          },
          "baseline": {
            "value": "top"
          },
          "align": {
            "value": "right"
          },
          "text": {
            "signal": "datum.tSel > 0 ? datum.tSel + '' de '' + datum.tN + '' seleccionada · clic de nuevo para limpiar'' : ''Clic en un tile para filtrar el informe''"
          },
          "fontSize": {
            "value": 10.5
          },
          "fontWeight": {
            "value": 500
          },
          "fill": {
            "value": "#5B6675"
          }
        }
      }
    },
    {
      "name": "cabeceraLinea",
      "type": "rule",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "signal": "headerH - 9"
          },
          "stroke": {
            "value": "#E2E8F0"
          },
          "strokeWidth": {
            "value": 1
          }
        }
      }
    },
    {
      "name": "tile",
      "type": "rect",
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "col",
            "field": "col"
          },
          "width": {
            "signal": "tileW"
          },
          "y": {
            "scale": "row",
            "field": "row"
          },
          "height": {
            "signal": "tileH"
          },
          "cornerRadius": {
            "value": 14
          },
          "fill": {
            "signal": "datum.activa ? ''#F2F7FF'' : ''#FFFFFF''"
          },
          "stroke": {
            "signal": "datum.activa ? ''#8FB2E6'' : ''#E8EDF5''"
          },
          "strokeWidth": {
            "signal": "datum.activa ? 1.6 : 1"
          },
          "opacity": {
            "field": "op"
          },
          "cursor": {
            "value": "pointer"
          },
          "tooltip": {
            "signal": "{''title'': datum[''Categoría''], ''Real'': pbiFormat(datum.Real, ''#,0''), ''Objetivo'': pbiFormat(datum.Objetivo, ''#,0''), ''Año anterior'': pbiFormat(datum[''Año anterior''], ''#,0''), ''Cumplimiento del objetivo'': datum.cumpl == null ? ''—'' : pbiFormat(datum.cumpl, ''0.0%''), ''Variación vs año anterior'': datum.varPy == null ? ''—'' : pbiFormat(datum.varPy, ''0.0%'')}"
          }
        }
      }
    },
    {
      "name": "tonoFranja",
      "type": "rect",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "col",
            "field": "col",
            "offset": 14
          },
          "x2": {
            "scale": "col",
            "field": "col",
            "offset": {
              "signal": "tileW - 14"
            }
          },
          "y": {
            "scale": "row",
            "field": "row",
            "offset": 8
          },
          "height": {
            "value": 4
          },
          "cornerRadius": {
            "value": 2
          },
          "fill": {
            "field": "tono"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "etiqueta",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "col",
            "field": "col",
            "offset": 14
          },
          "y": {
            "scale": "row",
            "field": "row",
            "offset": 26
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "top"
          },
          "text": {
            "field": "Categoría"
          },
          "limit": {
            "signal": "tileW - 28"
          },
          "fontSize": {
            "value": 12.5
          },
          "fontWeight": {
            "value": 700
          },
          "fill": {
            "value": "#1E293B"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "valorTexto",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "col",
            "field": "col",
            "offset": 14
          },
          "y": {
            "scale": "row",
            "field": "row",
            "offset": 44
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "top"
          },
          "text": {
            "signal": "pbiFormat(datum.Real, ''#,0,,.00M'')"
          },
          "fontSize": {
            "value": 15
          },
          "fontWeight": {
            "value": 700
          },
          "fill": {
            "value": "#0F172A"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "variacionTexto",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "col",
            "field": "col",
            "offset": {
              "signal": "tileW - 14"
            }
          },
          "y": {
            "scale": "row",
            "field": "row",
            "offset": 46
          },
          "align": {
            "value": "right"
          },
          "baseline": {
            "value": "top"
          },
          "text": {
            "signal": "datum.varPy == null ? \"\" : (datum.varPy >= 0 ? ''▲ +'' : ''▼ −'') + pbiFormat(abs(datum.varPy), ''0.0%'')"
          },
          "fontSize": {
            "value": 10.5
          },
          "fontWeight": {
            "value": 600
          },
          "fill": {
            "signal": "datum.varPy == null ? ''#4B5563'' : datum.varPy >= 0 ? ''#0F766E'' : ''#BE123C''"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "pistaColumna",
      "type": "rect",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "scale(''col'', datum.col) + tileW / 2 - barGap / 2 - acW - 4"
          },
          "width": {
            "signal": "acW + barGap + pyW + 8"
          },
          "y2": {
            "signal": "scale(''row'', datum.row) + tileH - bottomReserve"
          },
          "y": {
            "signal": "scale(''row'', datum.row) + tileH - bottomReserve - chartH"
          },
          "cornerRadius": {
            "value": 10
          },
          "fill": {
            "value": "#F3F6FA"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "barraPY",
      "type": "rect",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "scale(''col'', datum.col) + tileW / 2 + barGap / 2"
          },
          "width": {
            "signal": "pyW"
          },
          "y2": {
            "signal": "scale(''row'', datum.row) + tileH - bottomReserve"
          },
          "height": {
            "signal": "scale(''v'', datum[''Año anterior''])"
          },
          "cornerRadiusTopLeft": {
            "value": 3
          },
          "cornerRadiusTopRight": {
            "value": 3
          },
          "fill": {
            "value": "#7E8DA0"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "barraAC",
      "type": "rect",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "scale(''col'', datum.col) + tileW / 2 - barGap / 2 - acW"
          },
          "width": {
            "signal": "acW"
          },
          "y2": {
            "signal": "scale(''row'', datum.row) + tileH - bottomReserve"
          },
          "height": {
            "signal": "scale(''v'', datum.Real)"
          },
          "cornerRadiusTopLeft": {
            "value": 6
          },
          "cornerRadiusTopRight": {
            "value": 6
          },
          "fill": {
            "value": {
              "gradient": "linear",
              "x1": 0,
              "y1": 1,
              "x2": 0,
              "y2": 0,
              "stops": [
                {
                  "offset": 0,
                  "color": "#2E6BE0"
                },
                {
                  "offset": 1,
                  "color": "#16307A"
                }
              ]
            }
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "objetivoTick",
      "type": "rule",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "scale(''col'', datum.col) + tileW / 2 - barGap / 2 - acW - 3"
          },
          "x2": {
            "signal": "scale(''col'', datum.col) + tileW / 2 + barGap / 2 + pyW + 3"
          },
          "y": {
            "signal": "scale(''row'', datum.row) + tileH - bottomReserve - scale(''v'', datum.Objetivo)"
          },
          "stroke": {
            "value": "#0F172A"
          },
          "strokeWidth": {
            "value": 2.5
          },
          "strokeCap": {
            "value": "round"
          },
          "opacity": {
            "signal": "isValid(datum.Objetivo) ? datum.op : 0"
          }
        }
      }
    },
    {
      "name": "cumplimientoBadge",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "kpi"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "col",
            "field": "col",
            "offset": 14
          },
          "y": {
            "scale": "row",
            "field": "row",
            "offset": {
              "signal": "tileH - 10"
            }
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "signal": "datum.cumpl == null ? ''sin objetivo'' : pbiFormat(datum.cumpl, ''0.0%'') + '' del objetivo''"
          },
          "limit": {
            "signal": "tileW - 28"
          },
          "fontSize": {
            "value": 10.5
          },
          "fontWeight": {
            "value": 600
          },
          "fill": {
            "field": "tono"
          },
          "opacity": {
            "field": "op"
          }
        }
      }
    },
    {
      "name": "leyendaBandaSwatch",
      "type": "rect",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "value": 2
          },
          "width": {
            "value": 18
          },
          "y": {
            "signal": "height - footerH + 15 - 5"
          },
          "height": {
            "value": 7
          },
          "cornerRadius": {
            "value": 3.5
          },
          "fill": {
            "value": "#7E8DA0"
          }
        }
      }
    },
    {
      "name": "leyendaBandaTexto",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "24"
          },
          "y": {
            "signal": "height - footerH + 15"
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "value": "Año anterior"
          },
          "fontSize": {
            "value": 10.5
          },
          "fontWeight": {
            "value": 500
          },
          "fill": {
            "value": "#4B5563"
          }
        }
      }
    },
    {
      "name": "leyendaBarraSwatch",
      "type": "rect",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "value": 100
          },
          "width": {
            "value": 18
          },
          "y": {
            "signal": "height - footerH + 15 - 3.5"
          },
          "height": {
            "value": 9
          },
          "cornerRadius": {
            "value": 4.5
          },
          "fill": {
            "value": {
              "gradient": "linear",
              "x1": 0,
              "y1": 0,
              "x2": 1,
              "y2": 0,
              "stops": [
                {
                  "offset": 0,
                  "color": "#2E6BE0"
                },
                {
                  "offset": 1,
                  "color": "#16307A"
                }
              ]
            }
          }
        }
      }
    },
    {
      "name": "leyendaBarraTexto",
      "type": "text",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "122"
          },
          "y": {
            "signal": "height - footerH + 15"
          },
          "align": {
            "value": "left"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "value": "Real"
          },
          "fontSize": {
            "value": 10.5
          },
          "fontWeight": {
            "value": 500
          },
          "fill": {
            "value": "#4B5563"
          }
        }
      }
    },
    {
      "name": "leyendaObjetivoSwatch",
      "type": "rule",
      "interactive": false,
      "from": {
        "data": "resumen"
      },
      "encode": {
        "update": {
